import type { Plugin } from "../../kernel/types";

const stableTool = {
  name: "stable_value",
  version: "1.0.0",
  description: "Return the stable integer value 18.",
  permissions: [] as string[],
  sideEffect: "none" as const,
  parameters: {
    type: "object",
    properties: {},
    additionalProperties: false,
  } as const,
  outputSchema: {
    type: "object",
    properties: {
      ok: { type: "boolean" },
      data: { type: "number" },
    },
    required: ["ok", "data"],
  } as const,
  async handler(_args: Record<string, unknown>, _tctx: unknown) {
    return { ok: true as const, data: 18 };
  },
};

const plugin: Plugin = {
  id: "stable-plugin",
  name: "stable-plugin",
  version: "1.0.0",
  onLoad(ctx) {
    ctx.register({ kind: "tool", tool: stableTool });
  },
};

export default plugin;

